#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    struct Info {
        long long value;
        int count;
        int first;
    };
    vector<Info> items;
    unordered_map<long long, int> index;
    for (int i = 0; i < n; ++i) {
        long long x;
        cin >> x;
        auto it = index.find(x);
        if (it == index.end()) {
            index[x] = static_cast<int>(items.size());
            items.push_back({x, 1, i});
        } else {
            ++items[it->second].count;
        }
    }
    sort(items.begin(), items.end(), [](const Info& a, const Info& b) {
        if (a.count != b.count) return a.count > b.count;
        return a.first < b.first;
    });
    for (int i = 0; i < k; ++i) {
        if (i) cout << ' ';
        cout << items[i].value;
    }
    cout << '\n';
    return 0;
}

