#include <bits/stdc++.h>
using namespace std;

class Parser {
public:
    Parser(string input, const unordered_map<string, long long>& values)
        : text(move(input)), variables(values), pos(0) {}

    long long parseExpression() {
        long long value = parseTerm();
        while (true) {
            skipSpaces();
            if (match('+')) value += parseTerm();
            else if (match('-')) value -= parseTerm();
            else break;
        }
        return value;
    }

private:
    string text;
    const unordered_map<string, long long>& variables;
    size_t pos;

    void skipSpaces() {
        while (pos < text.size() && isspace(static_cast<unsigned char>(text[pos]))) ++pos;
    }

    bool match(char ch) {
        skipSpaces();
        if (pos < text.size() && text[pos] == ch) {
            ++pos;
            return true;
        }
        return false;
    }

    long long parseTerm() {
        long long value = parseFactor();
        while (true) {
            if (match('*')) value *= parseFactor();
            else break;
        }
        return value;
    }

    long long parseFactor() {
        skipSpaces();
        if (match('+')) return parseFactor();
        if (match('-')) return -parseFactor();
        if (match('(')) {
            long long value = parseExpression();
            match(')');
            return value;
        }
        if (pos < text.size() && isdigit(static_cast<unsigned char>(text[pos]))) {
            long long value = 0;
            while (pos < text.size() && isdigit(static_cast<unsigned char>(text[pos]))) {
                value = value * 10 + (text[pos++] - '0');
            }
            return value;
        }
        string name;
        while (pos < text.size() &&
               (isalnum(static_cast<unsigned char>(text[pos])) || text[pos] == '_')) {
            name.push_back(text[pos++]);
        }
        return variables.at(name);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int m;
    cin >> m;
    unordered_map<string, long long> variables;
    for (int i = 0; i < m; ++i) {
        string name;
        long long value;
        cin >> name >> value;
        variables[name] = value;
    }
    cin.ignore(numeric_limits<streamsize>::max(), '\n');
    string expression;
    getline(cin, expression);
    cout << Parser(expression, variables).parseExpression() << '\n';
    return 0;
}
